function applyRoleCapabilities(me){
  if(!me)return;
  document.body.dataset.authRole=me.role||'viewer';
  const admin=me.role==='admin',viewer=me.role==='viewer';
  const adminNav=$('#administrationNav');if(adminNav)adminNav.hidden=!admin;
  $$('[data-admin-only]').forEach(element=>element.hidden=!admin);
  ['#resetBtn','#supplierRegistryRefresh','#supplierEdrSync','#supplierNazkReviewSync','#frameworksRefresh',
   '#refNazkRefresh','#refAmcuUploadBtn','#bidsDataRefresh'].forEach(selector=>{
    const element=$(selector);if(!element)return;
    element.dataset.roleDisabled=admin?'0':'1';
    element.disabled=!admin||element.dataset.runtimeDisabled==='1';
    if(!admin)element.title='Дія доступна лише адміністратору';
    else if(element.dataset.runtimeDisabled!=='1')element.title='';
  });
  const requestsRefresh=$('#requestsRefresh');if(requestsRefresh){
    requestsRefresh.disabled=viewer||requestsRefresh.dataset.runtimeDisabled==='1';
    if(viewer)requestsRefresh.title='Дія недоступна для ролі лише перегляду';
    else if(requestsRefresh.dataset.runtimeDisabled!=='1')requestsRefresh.title='';
  }
  document.body.classList.toggle('role-viewer',viewer);
}
