function displayDate(value){if(!value)return '';if(/^\d{4}-\d{2}-\d{2}$/.test(String(value).trim()))return displayDateOnly(value);const d=new Date(value);return Number.isNaN(d.valueOf())?value:d.toLocaleString('uk-UA',{dateStyle:'short',timeStyle:'short'})}
function displayDateOnly(value){if(!value)return '';const text=String(value).trim(),iso=text.match(/^(\d{4})-(\d{2})-(\d{2})$/),ua=text.match(/^(\d{1,2})[./](\d{1,2})[./](\d{4})$/);if(iso)return`${iso[3]}.${iso[2]}.${iso[1]}`;if(ua)return`${ua[1].padStart(2,'0')}.${ua[2].padStart(2,'0')}.${ua[3]}`;const d=new Date(text);return Number.isNaN(d.valueOf())?text:d.toLocaleDateString('uk-UA',{day:'2-digit',month:'2-digit',year:'numeric'})}
function addCalendarDays(value,days=1){const match=String(value||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);if(!match)return'';const result=new Date(Date.UTC(Number(match[1]),Number(match[2])-1,Number(match[3])+days));return result.toISOString().slice(0,10)}
function mapRow(x){return {id:x.id,participant:x.supplier_name||'',edrpou:x.supplier_code||'',qualificationId:x.pretty_id||'',frameworkTitle:x.framework_title||'',dkCode:x.dk_code||'',category:x.category||'',marketplaceLink:x.marketplace_url||'',prozorroLink:x.pretty_id&&x.supplier_code?`https://prozorro.gov.ua/uk/framework/${encodeURIComponent(x.pretty_id)}/submissions?framework_tenderer=${encodeURIComponent(x.supplier_code)}`:'',receivedDate:displayDate(x.date_published),documents:[...(x.documents||[]),...(x.decision_documents||[])],protocolNumber:x.protocol_number||'',protocolDate:x.protocol_date||'',publicationDate:x.publication_date||'',protocolOfficer:x.protocol_officer||'',reviewOfficer:x.review_officer||'',protocolRemarks:x.protocol_remarks||'',protocolDecision:x.protocol_decision||'',marketplaceDecision:x.marketplace_decision||'',complianceStatus:x.compliance_status||'',complianceComments:x.compliance_comments||'',managerName:x.manager_name||x.manager_name_display||'',managerNameDisplay:x.manager_name_display||x.manager_name||'',managerNameDisplaySource:x.manager_name_display_source||'',managerNameDisplaySourceDate:x.manager_name_display_source_date||'',managerNameSource:x.manager_name_source||'',managerNameSourceSubmissionId:x.manager_name_source_submission_id||'',documentPackage:x.document_package||'',contractDetails:x.contract_details||'',documentCheckStatus:x.document_check_status||'',documentCheckSummary:x.document_check_summary||'',documentCheckCategories:x.document_check_categories||{},documentCheckedAt:displayDate(x.document_checked_at),generatedProtocolNumber:x.generated_protocol_number||'',generatedProtocolDate:x.generated_protocol_date||'',generatedProtocolDecision:x.generated_protocol_decision||'',protocolGeneratedAt:x.protocol_generated_at||'',authorityReview:x.authority_review||'',mvsSealReview:x.mvs_seal_review||'',decision:x.decision||'Очікує рішення',registryStatus:x.registry_status||'',registryValidUntil:displayDateOnly(x.registry_valid_until),registryStatusDate:displayDateOnly(x.registry_status_date),registryDocuments:x.registry_documents||[],amcuMatch:Boolean(x.amcu_match),nazkMatch:Boolean(x.nazk_match),nazkReviewResult:x.nazk_review_result||'',nazkCertificateRequired:Boolean(x.nazk_certificate_required),nazkCertificateChecked:Boolean(x.nazk_certificate_checked),nazkControlId:x.nazk_control_id||null,nazkState:x.nazk_state||'not_required',nazkCanApprove:x.nazk_can_approve!==false,nazkStateReason:x.nazk_state_reason||'',notes:x.notes||''}}
async function request(url,options={}){const headers={...(options.headers||{})};const localRole=$('#roleSelect')?.value;if(localRole)headers['X-PQM-Local-Role']=localRole;const r=await fetch(url,{...options,headers}),type=r.headers.get('content-type')||'',text=await r.text();let body={};if(type.includes('application/json')){try{body=JSON.parse(text)}catch{throw new Error('Сервер повернув пошкоджену JSON-відповідь')}}else if(text.trim().startsWith('{')||text.trim().startsWith('[')){try{body=JSON.parse(text)}catch{throw new Error('Сервер повернув неочікувану відповідь')}}else throw new Error(r.ok?'Сервер повернув HTML замість даних. Оновіть PQM і повторіть спробу.':`Помилка сервера ${r.status}`);if(!r.ok)throw new Error(body.error||body.message||'Помилка запиту');return body}
