function updateMultiSummary(id,placeholder,selection,labelFor=value=>value){const summary=$(`#${id} summary`),values=[...selection];summary.textContent=!values.length?placeholder:values.length===1?labelFor(values[0]):`${placeholder}: ${values.length}`}
function syncFilterUrl(){const url=new URL(location.href);[['search',$('#searchInput').value],['category',categoryFilter],['officer',officerFilter],['date_from',$('#dateFromFilter').value],['date_to',$('#dateToFilter').value]].forEach(([key,value])=>value?url.searchParams.set(key,value):url.searchParams.delete(key));history.replaceState(null,'',url)}
