function saveFilterState(){localStorage.setItem(filterStateKey,JSON.stringify({search:$('#searchInput').value,dateFrom:$('#dateFromFilter').value,dateTo:$('#dateToFilter').value,protocolDecision:$('#protocolDecisionFilter').value,complianceStatus:$('#complianceStatusFilter').value,officer:officerFilter,category:categoryFilter,sortKey,sortDirection,selections:Object.fromEntries(Object.entries(filterSelections).map(([key,value])=>[key,[...value]]))}));syncPrimaryFilters();syncFilterUrl()}
function restoreFilterState(){try{const state=JSON.parse(localStorage.getItem(filterStateKey)||'null')||{};const query=new URLSearchParams(location.search);$('#searchInput').value=query.get('search')??state.search??'';$('#dateFromFilter').value=query.get('date_from')??state.dateFrom??'';$('#dateToFilter').value=query.get('date_to')??state.dateTo??'';$('#protocolDecisionFilter').value=state.protocolDecision||'';$('#complianceStatusFilter').value=state.complianceStatus||'';officerFilter=query.get('officer')??state.officer??'';categoryFilter=query.get('category')??state.category??'';sortKey=state.sortKey||'receivedDate';sortDirection=state.sortDirection==='asc'?'asc':'desc';Object.entries(state.selections||{}).forEach(([key,values])=>{if(!filterSelections[key]||!Array.isArray(values))return;filterSelections[key].clear();values.forEach(value=>filterSelections[key].add(value))});$$('.multi-filter input[type="checkbox"]').forEach(input=>{input.checked=Object.values(filterSelections).some(selection=>selection.has(input.value))});syncPrimaryFilters()}catch{localStorage.removeItem(filterStateKey)}}
async function loadPrimaryFilterOptions(){try{const data=await request(`${API}/admin/frameworks`),categories=[...new Set((data.items||[]).map(x=>x.category).filter(Boolean))].sort(new Intl.Collator('uk-UA').compare);$('#applicationCategoryFilter').innerHTML='<option value="">Усі категорії</option>'+categories.map(value=>`<option value="${esc(value)}">${esc(value)}</option>`).join('');$('#applicationOfficerFilter').innerHTML='<option value="">Усі УО протоколу</option><option value="__unassigned__">Не призначено</option>'+protocolOfficers.map(value=>`<option value="${esc(value)}">${esc(formatOfficerName(value))}</option>`).join('');syncPrimaryFilters()}catch(error){console.warn('Primary filters unavailable',error)}}
function renderDynamicFilter(id,items,selection,valueFor,labelFor,placeholder){
  const details=$(`#${id}`),query=details.querySelector('.multi-search').value.trim().toLocaleLowerCase('uk-UA');
  const visible=items.filter(item=>labelFor(item).toLocaleLowerCase('uk-UA').includes(query));
  details.querySelector('.multi-options').innerHTML=visible.map(item=>{const value=valueFor(item);return `<label><input type="checkbox" value="${esc(value)}" ${selection.has(value)?'checked':''}> <span>${esc(labelFor(item))}</span></label>`}).join('')||'<p class="muted">Нічого не знайдено</p>';
  details.querySelectorAll('.multi-options input').forEach(input=>input.onchange=()=>{input.checked?selection.add(input.value):selection.delete(input.value);updateMultiSummary(id,placeholder,selection,value=>{const item=items.find(candidate=>valueFor(candidate)===value);return item?labelFor(item):value});page=1;loadRows()});
  updateMultiSummary(id,placeholder,selection,value=>{const item=items.find(candidate=>valueFor(candidate)===value);return item?labelFor(item):value});
}
async function loadFrameworks(){
  try {
    const data=await request(`${API}/frameworks`);
    frameworkOptions=data.items;
    renderDynamicFilter('frameworkFilter',frameworkOptions,filterSelections.framework,item=>item.id,item=>`${item.pretty_id} · ${item.title||''} · ${item.applications_count}`,'Усі відбори');
    const dkOptions=[...new Set(frameworkOptions.map(item=>item.dk_code).filter(Boolean))].sort().map(code=>({code}));
    const supplierDkOptions=$('#supplierRegistryDkOptions');
    if(supplierDkOptions)supplierDkOptions.innerHTML=dkOptions.map(item=>`<option value="${esc(item.code)}"></option>`).join('');
    renderDynamicFilter('dkFilter',dkOptions,filterSelections.dk,item=>item.code,item=>item.code,'Усі коди ДК');
  } catch(e) { toast(e.message) }
}
