function renderDocumentCheck(data){lastDocumentCheck=data;$('#documentCheckSubtitle').textContent=`${data.supplier_name} · ${data.supplier_code} · ${data.pretty_id}${data.checked_at?` · збережено ${displayDate(data.checked_at)}`:''}`;const status=data.counts.error?'error':data.counts.warning?'warning':'ok',headline=status==='error'?'Виявлено помилки':status==='warning'?'Є зауваження':'Перевірки пройдено';const groups=[['Підпис заявки',item=>!item.key.startsWith('mvs_')&&!item.key.startsWith('business_')&&item.key!=='contract_history'],['Витяг з МВС',item=>item.key.startsWith('mvs_')],['Підтвердження досвіду',item=>item.key.startsWith('business_')||item.key==='contract_history']];const row=item=>`<div class="check-row ${item.status} ${item.rows?.length?'with-table':''} ${item.key==='organization'?'informational':''}"><i>${item.status==='ok'?'✓':item.status==='error'?'×':'!'}</i><strong>${esc(item.label)}</strong><span>${esc(item.detail)}</span>${renderBusinessRows(item)}</div>`;const sections=groups.map(([title,test])=>{const items=data.checks.filter(test);return items.length?`<section class="check-section"><h3>${title}</h3><div class="check-list">${items.map(row).join('')}</div></section>`:''}).join('');$('#documentCheckBody').innerHTML=`<div class="check-summary ${status}"><strong>${headline}</strong><span>Перевірено <b>${data.counts.ok}</b></span><span>Попередження <b>${data.counts.warning}</b></span><span>Помилки <b>${data.counts.error}</b></span></div><div class="check-sections">${sections}</div>${data.notice?`<div class="check-notice">${esc(data.notice)}</div>`:''}`;$('#officialSignatureCheck').href=data.official_verification_url;if(!$('#documentCheckDialog').open)$('#documentCheckDialog').showModal()}
