async function verifyDocuments(){if(!activeDocsRow)return;const selection=$('#docsDialog').open?saveDocumentSelection(activeDocsRow):getDocumentSelection(activeDocsRow),selectionParam=Object.keys(selection).length?`&selection=${encodeURIComponent(JSON.stringify(selection))}`:'';if($('#docsDialog').open)$('#docsDialog').close();$('#documentCheckBody').innerHTML=`<p class="check-loading">${selectionParam?'Аналіз вибраних документів…':'Жоден файл не позначено — аналіз всього комплекту…'}</p>`;$('#documentCheckSubtitle').textContent=`${activeDocsRow.participant} · ${activeDocsRow.edrpou}`;if(!$('#documentCheckDialog').open)$('#documentCheckDialog').showModal();try{const started=await request(`${API}/applications/${encodeURIComponent(activeDocsRow.id)}/verify-documents/start?t=${Date.now()}${selectionParam}`);let job=started;let attempt=0;while(job.status==='running'){await new Promise(resolve=>setTimeout(resolve,750));job=await request(`${API}/document-check-jobs/${encodeURIComponent(started.job_id)}?t=${Date.now()}`);attempt++;if(attempt%8===0)$('#documentCheckBody').innerHTML=`<p class="check-loading">Перевірка триває… ${Math.round(attempt*0.75)} с</p>`}if(job.status==='error')throw new Error(job.error||'Не вдалося перевірити документи');if(job.status!=='complete')throw new Error('Не вдалося отримати результат перевірки');renderDocumentCheck(job.result);activeDocsRow.documentCheckStatus=job.result.counts.error?'error':job.result.counts.warning?'warning':'ok';activeDocsRow.documentCheckCategories=Object.fromEntries(Object.entries(job.result.category_results||{}).map(([key,value])=>[key,value.status]));activeDocsRow.documentCheckedAt=displayDate(job.result.checked_at||new Date().toISOString());renderInPlace()}catch(error){$('#documentCheckBody').innerHTML=`<div class="check-notice error">${esc(error.message)}</div>`}}
