async function applyBulk(e){
  e.preventDefault();const changes={};
  $$('[data-enable]:checked').forEach(x=>changes[fieldMap[x.dataset.enable]]=$(`[data-bulk="${x.dataset.enable}"]`).value.trim());
  if(!Object.keys(changes).length)return toast('Оберіть поля');
  if(Object.values(changes).some(value=>!String(value||'').trim()))return toast('Вкажіть значення для кожного вибраного поля');
  if(Object.hasOwn(changes,'protocol_date'))changes.publication_date=changes.protocol_date;
  const chosen=rows.filter(row=>selected.has(row.id));
  const effective=(row,key,rowKey)=>Object.hasOwn(changes,key)?changes[key]:row[rowKey];
  const admitWithRemarks=chosen.filter(row=>effective(row,'protocol_decision','protocolDecision')==='admit'&&String(effective(row,'protocol_remarks','protocolRemarks')||'').trim()!=='Без зауважень');
  if(admitWithRemarks.length)return toast(`Рішення УО «Так» неможливе: ${admitWithRemarks.length} заявок мають зауваження до протоколу`);
  const rejectWithoutGrounds=chosen.filter(row=>effective(row,'protocol_decision','protocolDecision')==='reject'&&String(effective(row,'protocol_remarks','protocolRemarks')||'').trim()==='Без зауважень'&&effective(row,'compliance_status','complianceStatus')==='approved');
  if(rejectWithoutGrounds.length)return toast(`Немає підстав для відхилення у ${rejectWithoutGrounds.length} заявках: комплаєнс погоджено та зауважень немає.`);
  if(changes.compliance_status==='approved'){const blocked=chosen.filter(row=>!row.nazkCanApprove);if(blocked.length)return toast(`Комплаєнс не погоджено: спочатку перевірте довідку НАЗК у ${blocked.length} заявках`)}
  const missingCompliance=chosen.some(row=>effective(row,'protocol_decision','protocolDecision')&&!effective(row,'compliance_status','complianceStatus'));if(missingCompliance)return toast('Спочатку визначте рішення комплаєнс');
  const changesLockedCompliance=Object.hasOwn(changes,'compliance_status')&&chosen.some(row=>changes.compliance_status!==row.complianceStatus&&row.protocolDecision);if(changesLockedCompliance)return toast('Щоб змінити комплаєнс, спочатку встановіть Рішення УО «Не визначено»');
  const conflict=chosen.some(row=>effective(row,'protocol_decision','protocolDecision')==='admit'&&effective(row,'compliance_status','complianceStatus')==='rejected');if(conflict)return toast('Рішення УО «Так» неможливе, коли комплаєнс не погоджено');
  try{await Promise.all([...selected].map(id=>request(`${API}/applications/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({...changes,role:role(),user:$('#roleSelect').selectedOptions[0].text})})));$('#bulkDialog').close();selected.clear();await loadRows();toast('Масові зміни застосовано')}catch(e2){toast(e2.message)}
}
