let supplierProcurementPage=1,supplierProcurementPages=1;
async function loadSupplierProcurements(){
  const code=$('#procurementSupplierCode').value.replace(/\D/g,'');
  if(!code)return;
  const body=$('#procurementSupplierBody');body.innerHTML='<tr><td colspan="6">Завантаження…</td></tr>';
  const params={page:supplierProcurementPage,size:'50',result:$('#procurementResult').value,dk_code:$('#procurementDkCodes').value,search:$('#procurementSearch').value.trim(),year:$('#procurementYear').value.trim(),date_from:$('#procurementDateFrom').value,date_to:$('#procurementDateTo').value};
  try{const data=await request(`${API}/supplier-procurements/${encodeURIComponent(code)}?${new URLSearchParams(params)}`);supplierProcurementPage=data.page;supplierProcurementPages=data.pages;const summary=data.summary||{};$('#procurementSupplierSummary').innerHTML=`<button type="button" data-procurement-result=""><span>Участей</span><strong>${frameworkNumber(summary.participations)}</strong></button><button type="button" data-procurement-result="wins"><span>Перемог</span><strong>${frameworkNumber(summary.wins)}</strong></button>`;$('#procurementTopDk').innerHTML=(data.top_dk||[]).map(x=>`<button type="button" data-procurement-dk="${esc(x.dk_code)}" title="${esc(x.dk_name||'')}">${esc(x.dk_code)} · ${frameworkNumber(x.procurements)}</button>`).join('');$('#procurementDkOptions').innerHTML=(data.top_dk||[]).map(x=>`<option value="${esc(x.dk_code)}">${esc(x.dk_name||'')}</option>`).join('');body.innerHTML=(data.items||[]).map(x=>`<tr><td><a href="https://prozorro.gov.ua/uk/tender/${encodeURIComponent(x.tender_id)}" target="_blank" rel="noopener">${esc(x.tender_id)}</a><small>${esc(x.title||'')}</small><small>${esc(x.dk_code||'')} ${esc(x.dk_name||'')}</small></td><td>${esc(displayDate(x.tender_date))||'—'}</td><td>${esc(x.buyer_name||'—')}</td><td>${esc(x.status||'—')}</td><td>${x.won?'<strong class="supplier-win">Перемога</strong>':'Участь'}</td><td>${frameworkNumber(x.amount)} ${esc(x.currency||'')}</td></tr>`).join('')||'<tr><td colspan="6">Записів не знайдено</td></tr>';$('#procurementSupplierInfo').textContent=`${Number(data.total||0).toLocaleString('uk-UA')} записів · сторінка ${data.page} із ${data.pages}`;$('#procurementSupplierPrev').disabled=data.page<=1;$('#procurementSupplierNext').disabled=data.page>=data.pages}catch(error){body.innerHTML=`<tr><td colspan="6">${esc(error.message)}</td></tr>`}
}
function openSupplierProcurements(code,winsOnly=false){$('#supplierProfileDialog').close();showModule('procurements');$('#procurementSupplierCode').value=code;$('#procurementResult').value=winsOnly?'wins':'';$('#procurementSearch').value=$('#procurementDkCodes').value=$('#procurementYear').value=$('#procurementDateFrom').value=$('#procurementDateTo').value='';supplierProcurementPage=1;loadSupplierProcurements()}

let adminFrameworkItems=[],adminFrameworkSort='pretty_id',adminFrameworkDirection='asc';
function renderAdminFrameworks(){
  const search=$('#adminFrameworkSearch').value.trim().toLocaleLowerCase('uk-UA'),status=$('#adminFrameworkStatus').value,category=$('#adminFrameworkCategory').value,officer=$('#adminFrameworkOfficer').value;
  let items=adminFrameworkItems.filter(x=>(!search||[x.pretty_id,x.title,x.dk_code].some(v=>String(v||'').toLocaleLowerCase('uk-UA').includes(search)))&&(!status||x.status===status)&&(!category||x.category===category)&&(!officer||(officer==='__unassigned__'?!x.responsible_officer:x.responsible_officer===officer)));
  const collator=new Intl.Collator('uk-UA',{numeric:true,sensitivity:'base'}),dir=adminFrameworkDirection==='asc'?1:-1;
  items.sort((a,b)=>collator.compare(String(a[adminFrameworkSort]||''),String(b[adminFrameworkSort]||''))*dir);
  $('#adminFrameworkCount').textContent=`Показано ${items.length} із ${adminFrameworkItems.length}`;
  $$('#adminFrameworksPanel [data-admin-sort]').forEach(th=>{th.classList.toggle('active-sort',th.dataset.adminSort===adminFrameworkSort);th.dataset.direction=th.dataset.adminSort===adminFrameworkSort?adminFrameworkDirection:''});
  $('#adminFrameworksBody').innerHTML=items.map(x=>`<tr data-directory-id="${esc(x.directory_id)}"><td><strong>${esc(x.pretty_id)}</strong><small>${esc(x.title||'')}</small></td><td>${esc(x.dk_code||'—')}</td><td><input data-admin-field="category" list="adminFrameworkCategoryOptions" value="${esc(x.category||'')}"></td><td><input data-admin-field="marketplace_url" value="${esc(x.marketplace_url||'')}"></td><td><select data-admin-field="responsible_officer">${officerOptions(x.responsible_officer)}</select></td><td><strong>${esc(x.status||'—')}</strong><small>${x.valid_until?`до ${esc(displayDateOnly(x.valid_until))}`:(x.missing_end_date?'немає кінцевої дати':'немає актуальних даних Prozorro')}</small></td><td>${x.pretty_id?`<a href="https://prozorro.gov.ua/uk/framework/${encodeURIComponent(x.pretty_id)}" target="_blank" rel="noopener">Відкрити</a>`:'—'}</td><td><button class="primary admin-framework-save">Зберегти</button></td></tr>`).join('')||'<tr><td colspan="8">За вибраними умовами відборів немає</td></tr>';
  $$('.admin-framework-save').forEach(button=>button.onclick=async()=>{const row=button.closest('tr'),payload={};row.querySelectorAll('[data-admin-field]').forEach(input=>payload[input.dataset.adminField]=input.value.trim());try{await request(`${API}/admin/frameworks/${encodeURIComponent(row.dataset.directoryId)}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});toast('Службові дані відбору збережено');await loadAdminFrameworks();if(activeModule==='workQueue')await loadWorkQueue()}catch(error){toast(error.message)}});
}
async function loadAdminFrameworks(){const body=$('#adminFrameworksBody');body.innerHTML='<tr><td colspan="8">Завантаження…</td></tr>';try{if(!protocolOfficers.length)await loadAuthorizedOfficers();const data=await request(`${API}/admin/frameworks`);adminFrameworkItems=data.items||[];const categories=[...new Set(adminFrameworkItems.map(x=>x.category).filter(Boolean))].sort(new Intl.Collator('uk-UA').compare),officers=[...new Set(adminFrameworkItems.map(x=>x.responsible_officer).filter(Boolean))].sort(new Intl.Collator('uk-UA').compare);const selectedCategory=$('#adminFrameworkCategory').value,selectedOfficer=$('#adminFrameworkOfficer').value;$('#adminFrameworkCategory').innerHTML='<option value="">Усі категорії</option>'+categories.map(v=>`<option ${v===selectedCategory?'selected':''}>${esc(v)}</option>`).join('');$('#adminFrameworkOfficer').innerHTML='<option value="">Усі УО</option><option value="__unassigned__">Не призначено</option>'+officers.map(v=>`<option ${v===selectedOfficer?'selected':''}>${esc(v)}</option>`).join('');$('#adminFrameworkCategoryOptions').innerHTML=categories.map(v=>`<option value="${esc(v)}">`).join('');renderAdminFrameworks()}catch(error){body.innerHTML=`<tr><td colspan="8">${esc(error.message)}</td></tr>`}}
async function addAdminFramework(){
  const prettyId=prompt('ID відбору');if(prettyId===null)return;
  const dkCode=prompt('Код ДК');if(dkCode===null)return;
  const category=prompt('Категорія','')??'';
  const marketplaceUrl=prompt('Посилання на майданчик','')??'';
  try{await request(`${API}/admin/frameworks`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pretty_id:prettyId,dk_code:dkCode,category,marketplace_url:marketplaceUrl})});toast('Відбір додано до службового довідника');await loadAdminFrameworks()}catch(error){toast(error.message)}
}
async function importNewAdminFrameworks(){
  if(!confirm('Імпортувати лише нові відбори з Google? Наявні значення PQM не будуть змінені.'))return;
  try{const data=await request(`${API}/admin/frameworks/import-new`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});toast(`Імпортовано: ${Number(data.imported||0)} · наявних: ${Number(data.existing_conflicts||0)} · пропущено: ${Number(data.skipped||0)}`);await loadAdminFrameworks()}catch(error){toast(error.message)}
}
async function loadAdminOfficers(){const body=$('#adminOfficersBody');body.innerHTML='<tr><td colspan="5">Завантаження…</td></tr>';try{const items=await loadAuthorizedOfficers(false);body.innerHTML=items.map(x=>`<tr data-officer-id="${x.id}"><td><strong>${esc(x.full_name)}</strong></td><td><input data-officer-role value="${esc(x.role||'УО')}"></td><td><label><input data-officer-active type="checkbox" ${x.active?'checked':''}> ${x.active?'Активна':'Історична'}</label></td><td>${Number(x.active_frameworks||0).toLocaleString('uk-UA')}</td><td><button class="primary admin-officer-save">Зберегти</button></td></tr>`).join('');$$('.admin-officer-save').forEach(button=>button.onclick=async()=>{const row=button.closest('tr');await request(`${API}/admin/officers/${row.dataset.officerId}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({role:row.querySelector('[data-officer-role]').value,active:row.querySelector('[data-officer-active]').checked})});toast('Довідник УО оновлено');await loadAdminOfficers()});await loadAdminUsers(items)}catch(error){body.innerHTML=`<tr><td colspan="5">${esc(error.message)}</td></tr>`}}
async function loadAdminTemplates(){const body=$('#adminTemplatesBody');body.innerHTML='<tr><td colspan="5">Завантаження…</td></tr>';try{const data=await request(`${API}/admin/templates`);body.innerHTML=(data.items||[]).map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td><code>${esc(x.key)}</code></td><td>${esc(x.filename)}</td><td>${esc(displayDate(x.modified_at))}</td><td class="admin-template-actions"><a class="ghost button-link" href="${API}/admin/templates/${encodeURIComponent(x.key)}/download">Завантажити</a><button type="button" class="primary" data-template-replace="${esc(x.key)}">Замінити шаблон</button></td></tr>`).join('')||'<tr><td colspan="5">Шаблони не знайдено</td></tr>';$$('[data-template-replace]').forEach(button=>button.onclick=()=>{const input=$('#adminTemplateFile');input.dataset.templateKey=button.dataset.templateReplace;input.click()})}catch(error){console.error('Template list unavailable',error);body.innerHTML='<tr><td colspan="5">Не вдалося завантажити шаблони. Повторіть спробу.</td></tr>'}}
async function replaceAdminTemplate(){const input=$('#adminTemplateFile'),file=input.files[0],key=input.dataset.templateKey;if(!file||!key)return;try{const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));await request(`${API}/admin/templates/${encodeURIComponent(key)}/replace`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:file.name,content:btoa(binary)})});toast('Шаблон перевірено та замінено');await loadAdminTemplates()}catch(error){toast(error.message)}finally{input.value='';delete input.dataset.templateKey}}
