async function loadSupplierEdrStatus(){
  try{
    const data=await request(`${API}/supplier-edr-sync-status?t=${Date.now()}`),state=data.state||{},last=data.last,oauth=data.oauth||{};
    supplierEdrOauth=oauth;
    const button=$('#supplierEdrSync');
    button.textContent=!oauth.configured?'Потрібен OAuth Client ID':!oauth.authorized?'Підключити Google':'Синхронізувати ЄДР';
    button.disabled=Boolean(state.running)||!oauth.configured;
    $('#supplierEdrSyncStatus').textContent=!oauth.configured
      ?'Безпечне підключення Google ще не налаштоване. Таблиця залишається закритою.'
      :!oauth.authorized?'OAuth налаштовано · потрібно один раз увійти через Google'
      :state.running?(state.message||'Синхронізація триває…')
      :last?`Довідник ЄДР: ${Number(data.total||0).toLocaleString('uk-UA')} записів · остання синхронізація ${displayDate(last.finished_at||last.started_at)} · ${last.status==='completed'?'успішно':'помилка'}`
      :'Google підключено · довідник ЄДР ще не синхронізовано';
    return {...state,oauth};
  }catch(error){console.error('Supplier EDR status request failed',error);$('#supplierEdrSyncStatus').textContent='Не вдалося отримати стан синхронізації ЄДР. Основна база постачальників залишається доступною.';return{}}
}
async function connectSupplierGoogle(){
  const popup=window.open('about:blank','pqm-google-oauth','width=620,height=760');
  if(!popup){toast('Браузер заблокував вікно входу. Дозвольте спливаючі вікна для 127.0.0.1');return}
  popup.document.write('<meta charset="utf-8"><body style="font:16px system-ui;padding:32px">Підготовка безпечного входу Google…</body>');
  popup.document.close();
  try{
    const data=await request(`${API}/google-oauth/start`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});
    popup.location.href=data.authorization_url;
  }catch(error){popup.document.body.innerHTML=`<h2>Не вдалося відкрити Google</h2><p>${esc(error.message)}</p>`;toast(error.message)}
}
let supplierEdrTimer=null;
async function startSupplierEdrSync(){
  try{
    $('#supplierEdrSync').disabled=true;
    await request(`${API}/supplier-edr-sync`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});
    $('#supplierEdrSyncStatus').textContent='Синхронізацію довідника ЄДР розпочато…';
    clearInterval(supplierEdrTimer);
    supplierEdrTimer=setInterval(async()=>{
      const state=await loadSupplierEdrStatus();
      if(!state.running){
        clearInterval(supplierEdrTimer);supplierEdrTimer=null;
        toast(state.error?'Синхронізація ЄДР завершилася з помилкою':'Довідник постачальників з ЄДР оновлено');
        try{await loadQualifiedSuppliersFiltered()}catch{}
      }
    },2000);
  }catch(error){$('#supplierEdrSync').disabled=false;toast(error.message)}
}
