async function loadRuntimeFeatures(){
  try{
    const features=await request(`${API}/runtime-features`);
    const banner=$('#environmentBanner');
    if(banner){
      const environment=String(features.environment||'local').toLowerCase();
      banner.textContent=environment==='local'
        ?'Локальна версія · ручні рішення не публікуються'
        :(['test','test_web','web'].includes(environment)
          ?'Тестова вебверсія · дані та дії не є робочим середовищем'
          :'Робоча вебверсія');
    }
    const disable=(selector,message)=>{const element=$(selector);if(!element)return;element.dataset.runtimeDisabled='1';element.disabled=true;element.title=message};
    if(!features.bids_update)disable('#bidsDataRefresh','Оновлення ProzorroBids вимкнено у цьому середовищі');
    if(features.bids_mode==='disabled'){
      disable('#bidsStatusRefresh','Локальна база ProzorroBids не підключена');
      $('#bidsSyncHeadline').textContent='ProzorroBids не підключено до TEST WEB';
    }
    if(!features.powerbi){
      disable('#powerbiExportBtn','Power BI доступний лише в локальному середовищі');
      $('#powerbiStatusMessage').textContent='Power BI вимкнено у TEST WEB';
    }
    if(!features.google){
      disable('#supplierEdrSync','Google OAuth не налаштовано для TEST WEB');
      disable('#supplierNazkReviewSync','Google OAuth не налаштовано для TEST WEB');
    }
    return features;
  }catch(error){return null}
}
